create or replace function public.create_enterprise_partner_campaign(p_network_id uuid,p_name text,p_campaign_type text default 'engagement',p_goal text default null) returns public.enterprise_partner_campaigns language plpgsql security definer set search_path=public,auth,extensions,pg_temp as $$ declare c public.enterprise_partner_campaigns; b uuid; begin select owner_business_id into b from public.enterprise_partner_networks where id=p_network_id; if b is null then raise exception 'network not found'; end if; if not exists(select 1 from public.business_members where business_id=b and user_id=auth.uid() and role in ('owner','admin')) then raise exception 'Enterprise partner admin access required'; end if; if not exists(select 1 from public.businesses where id=b and lower(business_tier::text) in ('fleet','enterprise')) then raise exception 'Fleet or Enterprise plan required'; end if; insert into public.enterprise_partner_campaigns(network_id,name,campaign_type,goal) values(p_network_id,p_name,p_campaign_type,p_goal) returning * into c; return c; end $$;
